/* cppi::1410fcfdc7910ac88e3528aea03d8188ede9f8f6d87cfd0aa84e1370031e4db4 */
select distinct request_id, start_date, end_date, pool, strategy_alternative, weight, start_date as business_date
from performance.tpm_tpm_atp_weights where request_id = 
(select max(request_id) from performance.tpm_tpm_atp_weights where start_date = '2025-05-26' and end_date = '2025-05-26')
and start_date = '2025-05-26' and end_date = '2025-05-26'

/* cppi::1e0753ab822a840c56ec1f02aaec28ffee22d83008d68058d7926f798efca301 */
select business_date as date_, security_id, 'SP500_35' as strategy_id, weight_ndo as weight
                                  from (select * from (select *, ROW_NUMBER() OVER (PARTITION by business_date, id_vendor_security_ndo, id_cppib_index order by feed_version asc) as rn from market.cppib_market_index_constituents_mapped_rimes) where rn = 1)
                                  where business_date >= date '2025-06-04' and business_date <= date '2025-06-06' and weight_ndo>0 and id_cppib_index = 'SP500_35_GR_USD_0_0' and security_id is not null

